from django.db import migrations, models
from django.utils import timezone

# An effet of ours due more than this many days ago is taken as debited by the bank.
RECENT_DUE_DAYS = 30


def add_lines(apps, schema_editor):
    """Every supplier payment recorded before D-208 gets its one line; our cheque or traite gets its effet issued,
    bank empty ("à compléter"), due on its cashing day (else the payment day): still issued when due in the last
    30 days or later, taken as debited when older."""
    SupplierPayment = apps.get_model("purchasing", "SupplierPayment")
    SupplierPaymentLine = apps.get_model("purchasing", "SupplierPaymentLine")
    Instrument = apps.get_model("treasury", "Instrument")
    InstrumentEvent = apps.get_model("treasury", "InstrumentEvent")
    recent = timezone.localdate() - dt.timedelta(days=RECENT_DUE_DAYS)
    for payment in SupplierPayment.objects.select_related("supplier").order_by("id").iterator():
        instrument = None
        reference = payment.reference
        if payment.method in ("cheque", "bill"):
            due_on = payment.cash_on or payment.paid_on
            status = "issued" if due_on >= recent else "debited"
            instrument = Instrument.objects.create(
                organization_id=payment.organization_id,
                direction="issued",
                kind=payment.method,
                number=(payment.reference or payment.number)[:50],
                drawer="",
                amount=payment.amount,
                issued_on=payment.paid_on,
                due_on=due_on,
                status=status,
                supplier_id=payment.supplier_id,
                source_number=payment.number,
                notes="Repris d'un règlement d'avant la trésorerie : banque à compléter.",
                created_by_id=payment.created_by_id,
            )
            InstrumentEvent.objects.create(
                organization_id=payment.organization_id,
                instrument=instrument,
                to_status="issued",
                happened_on=payment.paid_on,
            )
            if status != "issued":
                InstrumentEvent.objects.create(
                    organization_id=payment.organization_id,
                    instrument=instrument,
                    from_status="issued",
                    to_status=status,
                    happened_on=timezone.localdate(),
                    note="Repris : supposé débité.",
                )
            reference = ""
        SupplierPaymentLine.objects.create(
            organization_id=payment.organization_id,
            payment=payment,
            method=payment.method,
            amount=payment.amount,
            reference=reference,
            instrument=instrument,
        )


